                if pv>bv: bv=pv; best=ax
        tr=move(best)
        if tr>0.25:
            vv=DIRV[best]; cx+=vv[0]; cy+=vv[1]; cur=best
        L('cmove %s tr=%.2f pos %d,%d'%(best,tr,cx,cy))
